import * as THREE from 'three';
import {materials} from '../../core/index.js';
import {roundedRect} from '../../core/geometry.js';
export {THREE,materials,roundedRect};
export function mesh(parent,g,m,p=[0,0,0],name=''){const o=new THREE.Mesh(g,m);o.position.fromArray(p);o.name=name;parent.add(o);return o;}
export function box(parent,size,p,mat,name){return mesh(parent,new THREE.BoxGeometry(...size),mat,p,name);}
export function solid(shape,depth){const p=shape.extractPoints(16);if(!THREE.ShapeUtils.isClockWise(p.shape))p.shape.reverse();const s=new THREE.Shape(p.shape);for(const h of p.holes){if(THREE.ShapeUtils.isClockWise(h))h.reverse();s.holes.push(new THREE.Path(h));}return new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false});}
export function yzExtrude(shape,depth,y0=0){const g=solid(shape,depth),p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);p.setXYZ(i,x,y0-z,y);}g.computeVertexNormals();return g;}
export function rectHole(s,x,y,w,h){s.holes.push(roundedRect(w,h,.08,{cx:x,cy:y,path:new THREE.Path()}));return s;}
export function swept(section,{length=500,segments=300,start=0}={}){const ps=[],ix=[],n=section.length;for(let i=0;i<=segments;i++)for(const[y,z]of section)ps.push(start+length*i/segments,y,z);for(let i=0;i<segments;i++)for(let j=0;j<n;j++){const a=i*n+j,b=i*n+(j+1)%n,c=(i+1)*n+j,d=(i+1)*n+(j+1)%n;ix.push(a,b,d,a,d,c);}const caps=THREE.ShapeUtils.triangulateShape(section.map(v=>new THREE.Vector2(...v)),[]);for(const[a,b,c]of caps){ix.push(c,b,a);ix.push(segments*n+a,segments*n+b,segments*n+c);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(ps,3));g.setIndex(ix);g.computeVertexNormals();return g;}
export function tube(points,r=.45,sides=10){const ps=[],ix=[],N=points.length,up=new THREE.Vector3(0,0,1),last=new THREE.Vector3();let row;for(let i=0;i<N;i++){const t=points[Math.min(N-1,i+1)].clone().sub(points[Math.max(0,i-1)]).normalize();if(!i){row=up.clone().addScaledVector(t,-up.dot(t));if(row.lengthSq()<.01)row.set(0,1,0).addScaledVector(t,-t.y);row.normalize();}else row.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(last,t)).addScaledVector(t,-row.dot(t)).normalize();const cross=t.clone().cross(row);for(let j=0;j<sides;j++){const a=j*Math.PI*2/sides,v=points[i].clone().addScaledVector(row,Math.cos(a)*r).addScaledVector(cross,Math.sin(a)*r);ps.push(...v.toArray());}last.copy(t);}for(let i=0;i<N-1;i++)for(let j=0;j<sides;j++){const a=i*sides+j,b=i*sides+(j+1)%sides,c=(i+1)*sides+j,d=(i+1)*sides+(j+1)%sides;ix.push(a,b,d,a,d,c);}const ca=ps.length/3;ps.push(...points[0].toArray(),...points.at(-1).toArray());for(let j=0;j<sides;j++){ix.push(ca,(j+1)%sides,j);ix.push(ca+1,(N-1)*sides+j,(N-1)*sides+(j+1)%sides);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(ps,3));g.setIndex(ix);g.computeVertexNormals();return g;}
export function replaceGeometry(o,g){o.geometry.dispose();o.geometry=g;}
export function bakedBox(parent,size,p,mat,name){const g=new THREE.BoxGeometry(...size).translate(...p);return mesh(parent,g,mat,[0,0,0],name);}
